import pyomo.environ as pyo

DATA = {
    "foods": [
        "chicken_breast", "tofu", "spinach", "beef_steak",
        "eggs", "brown_rice", "bananas", "quinoa",
    ],
    "cost": {
        "chicken_breast": 7, "tofu": 7, "spinach": 1, "beef_steak": 9,
        "eggs": 6, "brown_rice": 7, "bananas": 2, "quinoa": 6,
    },
    "protein": {
        "chicken_breast": 12, "tofu": 10, "spinach": 11, "beef_steak": 8,
        "eggs": 16, "brown_rice": 4, "bananas": 4, "quinoa": 4,
    },
    "carbs": {
        "chicken_breast": 5, "tofu": 1, "spinach": 30, "beef_steak": 26,
        "eggs": 9, "brown_rice": 25, "bananas": 16, "quinoa": 20,
    },
    "calories": {
        "chicken_breast": 231, "tofu": 210, "spinach": 295, "beef_steak": 211,
        "eggs": 232, "brown_rice": 146, "bananas": 255, "quinoa": 205,
    },
    "requirement": {
        "protein": 91,
        "carbs": 136,
        "calories": 1563,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])

    # Binary selection variable: 1 if the food is chosen.
    model.x = pyo.Var(model.FOODS, within=pyo.Binary, bounds=(0, 1))

    # Objective: minimize total cost.
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Protein requirement.
    def protein_rule(m):
        return sum(d["protein"][i] * m.x[i] for i in m.FOODS) >= d["requirement"]["protein"]

    model.protein_req = pyo.Constraint(rule=protein_rule)

    # Carbohydrate requirement.
    def carbs_rule(m):
        return sum(d["carbs"][i] * m.x[i] for i in m.FOODS) >= d["requirement"]["carbs"]

    model.carbs_req = pyo.Constraint(rule=carbs_rule)

    # Calorie requirement.
    def calorie_rule(m):
        return sum(d["calories"][i] * m.x[i] for i in m.FOODS) >= d["requirement"]["calories"]

    model.calorie_req = pyo.Constraint(rule=calorie_rule)

    return model
